<?php
// Protected transaction-history page: displays demo activity with client-side search and filtering support.
declare(strict_types=1);
require_once __DIR__ . '/includes/auth.php'; require_login(); require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/helpers.php';
$stmt = db()->prepare('SELECT t.*, a.account_type FROM transactions t JOIN accounts a ON a.id = t.account_id WHERE a.user_id = ? ORDER BY t.transaction_date DESC'); $stmt->execute([$_SESSION['user_id']]); $transactions = $stmt->fetchAll();
$pageTitle = 'Transactions'; $portal = true; require __DIR__ . '/includes/header.php';
?>
<section class="portal-shell"><div class="portal-welcome"><div><p class="eyebrow">Transactions</p><h1>Follow every fictional movement.</h1><p>Search or filter the activity shown across your DDB accounts.</p></div></div><div class="transaction-toolbar"><div class="filter-group" role="group" aria-label="Filter transactions"><button class="filter-button active" type="button" data-filter="all">All</button><button class="filter-button" type="button" data-filter="income">Income</button><button class="filter-button" type="button" data-filter="payment">Payments</button><button class="filter-button" type="button" data-filter="transfer">Transfers</button></div><label class="search-box"><span class="sr-only">Search transactions</span><input id="transaction-search" type="search" placeholder="Search activity"><span aria-hidden="true">⌕</span></label></div><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable transaction history table"><table class="transactions-table"><caption class="sr-only">Transaction history</caption><thead><tr><th>Description</th><th>Date</th><th>Type</th><th>Account</th><th class="amount-cell">Amount</th></tr></thead><tbody><?php foreach ($transactions as $transaction): $amount=(float)$transaction['amount']; ?><tr data-transaction-row data-type="<?= e($transaction['transaction_type']) ?>" data-search="<?= e(strtolower($transaction['description'] . ' ' . $transaction['account_type'])) ?>"><td><strong><?= e($transaction['description']) ?></strong></td><td><?= e(date_label($transaction['transaction_date'])) ?></td><td><span class="type-label <?= e($transaction['transaction_type']) ?>"><?= e(ucfirst($transaction['transaction_type'])) ?></span></td><td><?= e($transaction['account_type']) ?></td><td class="amount-cell <?= $amount >= 0 ? 'amount-credit' : 'amount-debit' ?>"><span class="sr-only"><?= $amount >= 0 ? 'Credit ' : 'Debit ' ?></span><?= $amount >= 0 ? '+' : '−' ?><?= money(abs($amount)) ?></td></tr><?php endforeach; ?></tbody></table><p id="no-transactions" class="empty-state" hidden>No transactions match this view.</p></div></section>
<?php require __DIR__ . '/includes/footer.php'; ?>
